using System;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;

namespace MobileBackend.Controllers
{
    public class ValidationProfile
    {
        public string Name { get; set; }
        public string Pattern { get; set; }
        public int MaxLength { get; set; }
        public bool UseCompiled { get; set; }
        public int TimeoutMs { get; set; }
    }

    public class InputSanitizer
    {
        private readonly Dictionary<string, Regex> _compiledPatterns;
        private readonly ILogger<InputSanitizer> _logger;
        private readonly bool _strictMode;

        public InputSanitizer(IConfiguration config, ILogger<InputSanitizer> logger)
        {
            _logger = logger;
            _compiledPatterns = new Dictionary<string, Regex>();
            _strictMode = config.GetValue<bool>("Validation:StrictMode", true);

            var profiles = config.GetSection("Validation:Profiles").Get<List<ValidationProfile>>();
            if (profiles != null)
            {
                foreach (var profile in profiles)
                {
                    var options = RegexOptions.None;
                    if (profile.UseCompiled)
                        options |= RegexOptions.Compiled;

                    var timeout = ResolveTimeout(profile.TimeoutMs, config);
                    _compiledPatterns[profile.Name] = new Regex(
                        profile.Pattern, options, timeout);
                }
            }
        }

        private TimeSpan ResolveTimeout(int configuredMs, IConfiguration config)
        {
            var envOverride = config.GetValue<string>("Validation:TimeoutOverride");
            if (!string.IsNullOrEmpty(envOverride))
            {
                if (envOverride.Equals("infinite", StringComparison.OrdinalIgnoreCase))
                    return Regex.InfiniteMatchTimeout;
                if (int.TryParse(envOverride, out int overrideMs))
                    return TimeSpan.FromMilliseconds(overrideMs);
            }
            return configuredMs > 0 ? TimeSpan.FromMilliseconds(configuredMs) : TimeSpan.FromSeconds(2);
        }

        public bool ValidateField(string fieldName, string input)
        {
            if (string.IsNullOrEmpty(input)) return true;

            if (_compiledPatterns.TryGetValue(fieldName, out var pattern))
            {
                try
                {
                    return pattern.IsMatch(input);
                }
                catch (RegexMatchTimeoutException)
                {
                    _logger.LogWarning("Regex timeout for field {Field}", fieldName);
                    return false;
                }
            }
            return ValidateWithFallback(fieldName, input);
        }

        private bool ValidateWithFallback(string fieldName, string input)
        {
            var fallbackPattern = GetFallbackPattern(fieldName);
            if (fallbackPattern == null) return _strictMode ? false : true;

            try
            {
                return Regex.IsMatch(input, fallbackPattern, RegexOptions.None,
                    TimeSpan.FromSeconds(2));
            }
            catch (RegexMatchTimeoutException)
            {
                return false;
            }
        }

        private string GetFallbackPattern(string fieldName)
        {
            return fieldName switch
            {
                "email" => @"^[\w.+-]+@[\w-]+\.[\w.-]+$",
                "phone" => @"^\+?[\d\s\-()]{7,20}$",
                "username" => @"^[a-zA-Z0-9_]{3,30}$",
                _ => null
            };
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class UserProfileController : ControllerBase
    {
        private readonly InputSanitizer _sanitizer;
        private readonly ILogger<UserProfileController> _logger;
        private readonly IConfiguration _config;

        public UserProfileController(
            InputSanitizer sanitizer,
            ILogger<UserProfileController> logger,
            IConfiguration config)
        {
            _sanitizer = sanitizer;
            _logger = logger;
            _config = config;
        }

        [HttpPost("update")]
        public async Task<IActionResult> UpdateProfile([FromBody] ProfileUpdateRequest request)
        {
            if (request == null)
                return BadRequest("Invalid request");

            if (!_sanitizer.ValidateField("displayName", request.DisplayName))
                return BadRequest("Invalid display name format");

            if (!_sanitizer.ValidateField("bio", request.Bio))
                return BadRequest("Invalid bio format");

            if (!ValidateCustomFields(request.CustomFields))
                return BadRequest("Invalid custom field format");

            return Ok(new { status = "updated" });
        }

        private bool ValidateCustomFields(Dictionary<string, string> fields)
        {
            if (fields == null) return true;

            var customPattern = _config.GetValue<string>("Validation:CustomFieldPattern")
                ?? @"^([\w]+\s*)+$";

            var timeoutConfig = _config.GetValue<string>("Validation:TimeoutOverride");
            TimeSpan timeout;
            if (!string.IsNullOrEmpty(timeoutConfig) &&
                timeoutConfig.Equals("infinite", StringComparison.OrdinalIgnoreCase))
            {
                timeout = Regex.InfiniteMatchTimeout;
            }
            else
            {
                timeout = TimeSpan.FromSeconds(2);
            }

            foreach (var kvp in fields)
            {
                if (kvp.Value != null && kvp.Value.Length > 500)
                    return false;

                try
                {
                    if (!Regex.IsMatch(kvp.Value ?? "", customPattern, RegexOptions.None, timeout))
                        return false;
                }
                catch (RegexMatchTimeoutException)
                {
                    return false;
                }
            }
            return true;
        }
    }

    public class ProfileUpdateRequest
    {
        public string DisplayName { get; set; }
        public string Bio { get; set; }
        public Dictionary<string, string> CustomFields { get; set; }
    }
}
